    private fun normalized(value:String)=value.replace("_","").lowercase()
    fun characterColorFamily(id:String):String?=characters.firstOrNull{it.id==id}?.colorFamily?:themes[id]
    fun matched(partId:String,characterId:String):AndroidLoadoutVariant? { val list=when{partId.startsWith("body.")->bodies;partId.startsWith("glider.")->gliders;else->emptyList()}; characterParts[characterId]?.get(partId)?.let { exact -> return list.firstOrNull { it.id==exact } }; val family=characterColorFamily(characterId)?:return null;return list.firstOrNull{it.baseId==partId&&normalized(it.colorFamily)==normalized(family)} }
    fun byId(id:String?)=(characters+bodies+gliders).firstOrNull{it.id==id}
    fun characterParts(base:List<AndroidBuildPart>):List<AndroidBuildPart> = (base + characters.mapNotNull { variant -> base.firstOrNull { it.id==variant.baseId }?.let { it.copy(sourceAssetIndex=variant.order,id=variant.id,name=it.name+" · "+variant.name,assetOverride=variant.assetPath) } }).sortedBy(AndroidBuildPart::sourceAssetIndex)
}
